mapper.select:
select hour,sum(pv) as pv from t_link_access_stats
where gid = #{gid} and full_short_url = #{fullShortUrl} and date between #{start} and #{end} and del_flag = 0
group by hour;

select weekday,sum(pv) as pv from t_link_access_stats
where gid = #{gid} and full_short_url = #{fullShortUrl} and date between #{start} and #{end} and del_flag = 0
group by weekday;
